/* UI helpers — shared bank/branch <select> population. */
window.TWBankUI = (function () {
  var D = window.TW_BANKS || { banks: [], branches: {} };
  function fillBanks(sel, selectedCode) {
    if (!sel) return;
    var html = '<option value="">— 請選擇銀行 —</option>';
    for (var i = 0; i < D.banks.length; i++) {
      var b = D.banks[i];
      html += '<option value="' + b.c + '"' + (b.c === selectedCode ? ' selected' : '') + '>' + b.c + ' ' + b.n + '</option>';
    }
    sel.innerHTML = html;
  }
  function fillBranches(sel, bankCode, selectedCode) {
    if (!sel) return;
    var list = D.branches[bankCode] || [];
    var html = '<option value="">' + (bankCode ? '— 請選擇分行 —' : '— 請先選擇銀行 —') + '</option>';
    for (var i = 0; i < list.length; i++) {
      var full = bankCode + list[i][0];           // reconstruct 7-digit code
      html += '<option value="' + full + '"' + (full === selectedCode ? ' selected' : '') + '>' + full + ' ' + list[i][1] + '</option>';
    }
    sel.innerHTML = html;
    sel.disabled = !bankCode;
  }
  function bankName(code) { for (var i = 0; i < D.banks.length; i++) if (D.banks[i].c === code) return D.banks[i].n; return ''; }
  function branchName(bankCode, fullCode) {
    var list = D.branches[bankCode] || [], sfx = String(fullCode || '').slice(3);
    for (var i = 0; i < list.length; i++) if (list[i][0] === sfx) return list[i][1];
    return '';
  }
  return { fillBanks: fillBanks, fillBranches: fillBranches, bankName: bankName, branchName: branchName };
})();
